# Smooth paths explicitly start from their planned endpoint; pauses settle the PD lag.
def execute_xyz(points, note='', cams=['practice_cam']):
 a=np.column_stack([np.asarray(points),np.tile(Q,(len(points),1))]);res=None
 for i in range(0,len(a),180):res=run(a[i:i+180],note=note,cams=cams)
 return res

def segments(keys):
 # each key is (x,y,z,duration); interpolate from previous key, first is initial point
 p=np.array(keys[0][:3]);out=[p.copy()]
 for key in keys[1:]:
  q=np.array(key[:3]);n=max(1,round(key[3]/.05));out.extend(np.linspace(p,q,n+1)[1:]);p=q
 return np.array(out)

