import numpy as np
from scipy import ndimage as ndi
from PIL import Image, ImageDraw
MM=.22186035
labels=np.load('/app/output/target_labels.npy')
def boundaries(m):
 # Clockwise oriented grid-edge chains.
 edges={}
 for y,x in zip(*np.where(m)):
  if y==0 or not m[y-1,x]:edges[(x,y)]=(x+1,y)
  if x==m.shape[1]-1 or not m[y,x+1]:edges[(x+1,y)]=(x+1,y+1)
  if y==m.shape[0]-1 or not m[y+1,x]:edges[(x+1,y+1)]=(x,y+1)
  if x==0 or not m[y,x-1]:edges[(x,y+1)]=(x,y)
 out=[]
 while edges:
  a=next(iter(edges));p=[a];b=edges.pop(a)
  while b!=a and b in edges:
   p.append(b);b=edges.pop(b)
  if len(p)>5:
   arr=np.array(p,dtype=float)-.5
   arr=ndi.gaussian_filter1d(arr,1.2,axis=0,mode='wrap')
   out.append(arr)
 return out

def make_path(m,outer=.65,inner=2.3,spacing=2.0):
 dist=ndi.distance_transform_edt(m)*MM
 levels=[outer]+list(np.arange(inner,float(dist.max()),spacing))
 paths=[]
 for lev in levels[::-1]:
  cs=boundaries(dist>=lev)
  for c in sorted(cs,key=len,reverse=True): paths.append((c,1.7 if lev==outer else 3.0,lev))
 center=np.array(np.unravel_index(dist.argmax(),dist.shape))[::-1]
 out=[[*center,3.0]]
 for c,depth,lev in paths:
  k=np.argmin(np.linalg.norm(c-np.array(out[-1][:2]),axis=1));c=np.roll(c,-k,axis=0)
  out.append([*c[0],depth]);out.extend([[*p,depth] for p in c[1:]]);out.append([*c[0],depth])
 return np.array(out),levels

if __name__=='__main__':
 p,l=make_path(labels==1);np.save('/app/output/dot_path.npy',p)
 im=Image.open('/app/target.png').convert('RGB');d=ImageDraw.Draw(im)
 d.line([tuple(x[:2]) for x in p],fill=(255,40,40),width=2);im.crop((310,240,430,360)).resize((720,720)).save('/app/output/dot_plan.png');print(l,len(p))
